const ONES: [&str; 20] = [
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
    "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",
    "nineteen",
];

const TENS: [&str; 10] = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
];

const SCALES: [&str; 6] = [
    "million", "billion", "trillion", "quadrillion", "quintillion", "sextillion",
];

/// Spells out a number below 100, e.g. `22` -> `"twenty-two"`.
fn below_hundred(n: u64) -> String {
    if n < 20 {
        ONES[n as usize].to_string()
    } else {
        let (tens, ones) = (n / 10, n % 10);
        if ones == 0 {
            TENS[tens as usize].to_string()
        } else {
            format!("{}-{}", TENS[tens as usize], ONES[ones as usize])
        }
    }
}

/// Spells out a number below 1000, e.g. `123` -> `"one hundred twenty-three"`.
fn below_thousand(n: u64) -> String {
    let (hundreds, rest) = (n / 100, n % 100);
    let mut text = String::new();
    if hundreds > 0 {
        text.push_str(ONES[hundreds as usize]);
        text.push_str(" hundred");
    }
    if rest > 0 {
        if !text.is_empty() {
            text.push(' ');
        }
        text.push_str(&below_hundred(rest));
    }
    text
}

/// Spells out any `u64` in English, e.g. `12345` -> `"twelve thousand three hundred forty-five"`.
///
/// The number is split into chunks of three digits; each non-zero chunk is
/// spelled out and followed by its scale word (`thousand`, `million`, ...).
pub fn encode(n: u64) -> String {
    if n == 0 {
        return "zero".to_string();
    }

    let mut chunks = Vec::new();
    let mut value = n;
    while value > 0 {
        chunks.push(value % 1000);
        value /= 1000;
    }

    let mut parts = Vec::new();
    for (i, &chunk) in chunks.iter().rev().enumerate() {
        if chunk == 0 {
            continue;
        }
        let scale = chunks.len() - 1 - i;
        let mut part = below_thousand(chunk);
        if scale > 0 {
            part.push(' ');
            part.push_str(SCALES[scale - 1]);
        }
        parts.push(part);
    }

    parts.join(" ")
}

